{"command":"create","path":"/tmp/contract/render.py","file_text":"import json, sys

d = json.load(open('/workspace/contracts/openapi.contract.json'))
comps = d.get('components', {}).get('schemas', {})

def render(schema, indent=0, seen=None):
    if seen is None:
        seen = set()
    pad = '  ' * indent
    if schema is None:
        return pad + '(none)'
    if '$ref' in schema:
        name = schema['$ref'].split('/')[-1]
        if name in seen:
            return pad + f'ref:{name}(recursive)'
        return pad + f'ref:{name}\n' + render(comps[name], indent + 1, seen | {name})
    if 'allOf' in schema:
        parts = [render(s, indent, seen) for s in schema['allOf']]
        return ('\n').join(parts)
    if 'oneOf' in schema:
        parts = [render(s, indent + 1, seen) for s in schema['oneOf']]
        return pad + 'oneOf:\n' + ('\n').join(parts)
    t = schema.get('type')
    if t == 'object':
        req = set(schema.get('required', []))
        ap = schema.get('additionalProperties', True)
        lines = [pad + 'object' + ('' if ap is False else ' [+extra]')]
        for k, v in (schema.get('properties') or {}).items():
            mark = '*' if k in req else ''
            lines.append(pad + f'  {k}{mark}:')
            lines.append(render(v, indent + 2, seen))
        return '\n'.join(lines)
    if t == 'array':
        return pad + 'array of:\n' + render(schema.get('items'), indent + 1, seen)
    s = pad + str(t)
    if 'enum' in schema:
        s += ' enum' + json.dumps(schema['enum'])
    if 'format' in schema:
        s += f" fmt:{schema['format']}"
    if 'default' in schema:
        s += f" default={json.dumps(schema['default'])}"
    for c in ('minimum', 'maximum', 'minLength', 'maxLength', 'exclusiveMinimum'):
        if c in schema:
            s += f' {c}={schema[c]}'
    return s

ops_filter = sys.argv[1:] if len(sys.argv) > 1 else None
for path, ops in d['paths'].items():
    for m, op in ops.items():
        oid = op.get('operationId')
        if ops_filter and oid not in ops_filter and path not in ops_filter:
            continue
        print('=' * 100)
        sec = 'AUTH' if op.get('security') else 'OPEN'
        print(f"{m.upper()} {path}  [{oid}] ({sec})")
        for p in op.get('parameters') or []:
            print(f"  param {p['name']} in={p['in']} required={p.get('required')}")
            print(render(p.get('schema'), 2))
        rb = op.get('requestBody')
        if rb:
            print('  REQUEST:')
            print(render(rb['content']['application/json']['schema'], 2))
        print('  RESPONSES:')
        for code, resp in op['responses'].items():
            c = resp.get('content', {}).get('application/json', {}).get('schema')
            if c and 'properties' in c and set(c.get('properties', {})) == {'error', 'code'}:
                codes = c['properties']['code'].get('enum')
                print(f"    {code}: error codes={codes}")
            else:
                print(f"    {code}:")
                print(render(c, 3))
"}

