	if !validUUID(req.LocationID) {
		writeErr(w, 404, "not_found", "location not found")
		return
	}
	l, err := loadLocation(req.LocationID)
	if err != nil {
		writeErr(w, 404, "not_found", "location not found")
		return
	}
	l.Functions[req.Function] = *req.Active
	db.Exec(`UPDATE locations SET functions=$2 WHERE location_id=$1`, l.LocationID, mustJSON(l.Functions))
	audit(user.UserID, sess.ActiveRole, "set_location_function_status", "location", l.LocationID, true, map[string]any{"function": req.Function, "active": *req.Active})
	recomputeServiceabilitySnapshot()
	writeData(w, 200, map[string]any{
		"locationId": l.LocationID,
		"function":   req.Function,
		"active":     *req.Active,
		"functions":  locationFunctionsJSON(l),
	})
}

