func handleCreateConnection(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		FromLocationID string   `json:"fromLocationId"`
		ToLocationID   string   `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         bool     `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.FromLocationID == "" || req.ToLocationID == "" || req.TravelMinutes == nil || req.CostUnits == nil || req.Active == nil {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	if *req.TravelMinutes < 1 || *req.CostUnits < 0 || req.FromLocationID == req.ToLocationID {
		writeErr(w, 400, "invalid_connection", "invalid connection parameters")
		return
	}
	if !validUUID(req.FromLocationID) || !validUUID(req.ToLocationID) {
		writeErr(w, 400, "invalid_connection", "location ids must be uuids")
		return
	}
	if _, err := loadLocation(req.FromLocationID); err != nil {
		writeErr(w, 400, "invalid_connection", "from location not found")
		return
	}
	if _, err := loadLocation(req.ToLocationID); err != nil {
		writeErr(w, 400, "invalid_connection", "to location not found")
		return
	}
	connectionID := newUUID()
	_, err := db.Exec(`INSERT INTO connections (connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity)
		VALUES ($1,$2,$3,$4,$5,$6,$7,'{"capacityUnits":0,"cooledCapacityUnits":0}')`,
		connectionID, req.FromLocationID, req.ToLocationID, *req.TravelMinutes, *req.CostUnits, req.Cooled, *req.Active)
	if err != nil {
		writeErr(w, 500, "internal_error", "failed to create connection")
		return
	}
	audit(user.UserID, sess.ActiveRole, "create_connection", "connection", connectionID, true, map[string]any{"from": req.FromLocationID, "to": req.ToLocationID})
	recomputeServiceabilitySnapshot()
	writeData(w, 201, map[string]any{
		"connectionId":   connectionID,
		"fromLocationId": req.FromLocationID,
		"toLocationId":   req.ToLocationID,
		"travelMinutes":  *req.TravelMinutes,
		"costUnits":      *req.CostUnits,
		"cooled":         req.Cooled,
		"active":         *req.Active,
	})
}

