// journeyPlanJSON renders the full dispatcher JourneyPlan shape.
func journeyPlanJSON(j *Journey, depth int) map[string]any {
	assignments := loadJourneyAssignments(j.JourneyID)
	stops := []any{}
	for _, s := range j.Stops {
		stops = append(stops, stopJSON(s))
	}
	legs := []any{}
	workerIDs := []string{}
	collectionIDs := []string{}
	nodeIDs := []string{}
	labIDs := []string{}
	transportIDs := []string{}
	seenWorker := map[string]bool{}
	for _, a := range assignments {
		legs = append(legs, legJSON(a))
		switch a.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, a.AssignmentID)
		case "node":
			nodeIDs = append(nodeIDs, a.AssignmentID)
		case "laboratory":
			labIDs = append(labIDs, a.AssignmentID)
		case "transport":
			transportIDs = append(transportIDs, a.AssignmentID)
		}
		if a.WorkerID != nil && !seenWorker[*a.WorkerID] {
			seenWorker[*a.WorkerID] = true
			workerIDs = append(workerIDs, *a.WorkerID)
		}
	}
	out := map[string]any{
		"journeyId":     j.JourneyID,
		"planVersion":   j.PlanVersion,
		"routeMode":     j.RouteMode,
		"status":        j.Status,
		"sampleIds":     j.SampleIDs,
		"orderedStops":  stops,
		"legs":          legs,
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = *j.ParentJourneyID
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
	}
	if j.TotalCostUnits > 0 {
		out["totalCostUnits"] = j.TotalCostUnits
	}
	// capacity summary across reserved resources
	var used, available int
	for _, sid := range j.SampleIDs {
		var u int
		db.QueryRow(`SELECT COALESCE(SUM(units),0) FROM capacity_reservations WHERE sample_id=$1 AND NOT released`, sid).Scan(&u)
		used += u
	}
	out["capacityUsed"] = used
	out["capacityAvailable"] = available
	if len(workerIDs) > 0 {
		out["assignedWorkerIds"] = workerIDs
	}
	if len(collectionIDs) > 0 {
		out["collectionAssignmentId"] = collectionIDs[0]
		out["collectionAssignmentIds"] = collectionIDs
	}
	if len(nodeIDs) > 0 {
		out["nodeAssignmentIds"] = nodeIDs
	}
	if len(labIDs) > 0 {
		out["laboratoryAssignmentIds"] = labIDs
	}
	if len(transportIDs) > 0 {
		out["firstTransportAssignmentId"] = transportIDs[0]
		out["finalTransportAssignmentId"] = transportIDs[len(transportIDs)-1]
		if len(transportIDs) > 2 {
			out["middleTransportAssignmentId"] = transportIDs[1]
		}
	}
	out["valid"] = j.Valid
	if j.ReplanStatus != nil {
		out["replanStatus"] = *j.ReplanStatus
	}
	if depth < 2 {
		if j.SplitJourneyID != nil {
			if sj, err := loadJourney(*j.SplitJourneyID); err == nil {
				out["splitJourney"] = journeyPlanJSON(sj, depth+1)
			}
		}
		if j.ReplacementJourneyID != nil {
			if rj, err := loadJourney(*j.ReplacementJourneyID); err == nil {
				out["replacementJourney"] = journeyPlanJSON(rj, depth+1)
			}
		}
	}
	return out
}

// workerJourneyPlanJSON renders the scoped worker view of a journey.
func workerJourneyPlanJSON(j *Journey, workerID string) map[string]any {
	assignments := loadJourneyAssignments(j.JourneyID)
	legs := []any{}
	assignmentIDs := []string{}
	collectionIDs := []string{}
	nodeIDs := []string{}
	labIDs := []string{}
	for _, a := range assignments {
		mine := (a.WorkerID != nil && *a.WorkerID == workerID) || (a.OfferedTo != nil && *a.OfferedTo == workerID)
		if !mine {
			continue
		}
		legs = append(legs, legJSON(a))
		assignmentIDs = append(assignmentIDs, a.AssignmentID)
		switch a.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, a.AssignmentID)
		case "node":
			nodeIDs = append(nodeIDs, a.AssignmentID)
		case "laboratory":
			labIDs = append(labIDs, a.AssignmentID)
		}
	}
	stops := []any{}
	for _, s := range j.Stops {
		stops = append(stops, stopJSON(s))
	}
	out := map[string]any{
		"journeyId":     j.JourneyID,
		"planVersion":   j.PlanVersion,
		"routeMode":     j.RouteMode,
		"status":        j.Status,
		"scope":         "assigned_legs",
		"assignmentIds": assignmentIDs,
		"legs":          legs,
		"orderedStops":  stops,
		"sampleIds":     j.SampleIDs,
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = *j.ParentJourneyID
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
	}
	if len(collectionIDs) > 0 {
		out["collectionAssignmentIds"] = collectionIDs
	}
	if len(nodeIDs) > 0 {
		out["nodeAssignmentIds"] = nodeIDs
	}
	if len(labIDs) > 0 {
		out["laboratoryAssignmentIds"] = labIDs
	}
	if len(assignmentIDs) > 0 {
		out["assignedWorkerIds"] = []string{workerID}
	}
	return out
}

