  const [lat, setLat] = useState("12.9716");
  const [lon, setLon] = useState("77.5946");
  const [originNodeId, setOriginNodeId] = useState("");
  const [sampleTypeId, setSampleTypeId] = useState("");
  const [deadline, setDeadline] = useState("");
  const [containerType, setContainerType] = useState("");
  const [tempMin, setTempMin] = useState("");
  const [tempMax, setTempMax] = useState("");

  return (
    <details style={{ marginTop: 12 }}>
      <summary>Register a pre-sealed sample I currently hold</summary>
      <form
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          const body: Record<string, any> = {
            origin: { latitude: Number(lat), longitude: Number(lon) },
            originType,
            requestedAt: nowIso(),
            deliveryDeadline: localToIso(deadline),
            sampleTypeId: sampleTypeId.trim(),
            containerType: containerType.trim(),
            temperatureMinC: Number(tempMin),
            temperatureMaxC: Number(tempMax),
            idempotencyKey: idemKey(),
          };
          if (originType === "node" && originNodeId.trim())
            body.originNodeId = originNodeId.trim();
          act("/api/ingest-presealed-sample", body, "Pre-sealed sample registered");
        }}
      >
        <div className="form-grid" style={{ marginTop: 8 }}>
          <label>
            Origin type
            <select value={originType} onChange={(e) => setOriginType(e.target.value)}>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </label>
          <label>
            Origin latitude
            <input value={lat} onChange={(e) => setLat(e.target.value)} required />
          </label>
          <label>
            Origin longitude
            <input value={lon} onChange={(e) => setLon(e.target.value)} required />
          </label>
          {originType === "node" && (
            <label>
              Origin node ID
              <input value={originNodeId} onChange={(e) => setOriginNodeId(e.target.value)} />
            </label>
          )}
          <label>
            Sample type ID
            <input
              value={sampleTypeId}
              onChange={(e) => setSampleTypeId(e.target.value)}
              required
            />
          </label>
          <label>
            Delivery deadline
            <input
              type="datetime-local"
              value={deadline}
              onChange={(e) => setDeadline(e.target.value)}
              required
            />
          </label>
          <label>
            Container type
            <input
              value={containerType}
              onChange={(e) => setContainerType(e.target.value)}
              required
            />
          </label>
          <label>
            Min temperature °C
            <input value={tempMin} onChange={(e) => setTempMin(e.target.value)} required />
          </label>
          <label>
            Max temperature °C
            <input value={tempMax} onChange={(e) => setTempMax(e.target.value)} required />
          </label>
        </div>
        <button className="primary" type="submit">
          Register pre-sealed sample
        </button>
      </form>
    </details>
  );
}

function WorkItemCard({
  item,
  user,
  act,
  onOpenSample,
  readOnly,
}: {
  item: any;
  user: UserInfo;
  act: ActFn;
  onOpenSample: (id: string) => void;
  readOnly?: boolean;
}) {
  const kind: string = item.kind || "assignment";
  const status: string = item.status || "";
  const assignmentId: string | undefined = item.assignmentId || item.assignment_id;
  const sampleId: string | undefined = item.sampleId || item.sample_id;
  const offered = status === "offered" || status === "pending";
  const active = status === "accepted" || status === "in_progress";

  return (
    <div className="panel" style={{ background: "#fbfcfd" }}>
      <div className="row">
        <span className="badge info">{kind}</span>
        <span className={`badge ${status === "completed" ? "ok" : offered ? "warn" : "info"}`}>
          {status}
        </span>
        {assignmentId && <span className="mono">assignment {shortId(assignmentId)}</span>}
        {sampleId && (
          <button onClick={() => onOpenSample(sampleId)}>Sample {shortId(sampleId)}</button>
        )}
        {item.offerExpiresAt && (
          <span className="muted">offer expires {fmtTime(item.offerExpiresAt)}</span>
        )}
      </div>
      <div className="muted" style={{ marginTop: 4 }}>
        {item.fromLocationId && <>from {shortId(item.fromLocationId)} </>}
        {item.toLocationId && <>to {shortId(item.toLocationId)} </>}
        {item.nodeId && <>node {shortId(item.nodeId)} </>}
        {item.laboratoryId && <>laboratory {shortId(item.laboratoryId)} </>}
        {item.deliveryDeadline && <>deadline {fmtTime(item.deliveryDeadline)} </>}
      </div>
      {item.destinationCapacity && (
        <div className="muted" style={{ marginTop: 4 }} aria-label="Destination capacity">
          Destination capacity: {capacityText(item.destinationCapacity)}
        </div>
      )}
      {!readOnly && assignmentId && (
        <AssignmentActions
          item={item}
          user={user}
          act={act}
          offered={offered}
          active={active}
          assignmentId={assignmentId}
          sampleId={sampleId}
        />
      )}
      {Array.isArray(item.history) && item.history.length > 0 && (
        <details>
          <summary>Status timeline ({item.history.length})</summary>
          <ul className="timeline" style={{ marginTop: 8 }}>
            {item.history.map((h: any, i: number) => (
              <li key={h.eventId ?? i}>
                <div className="t-time">{fmtTime(h.occurredAt)}</div>
                <div className="t-action">{h.action}</div>
                <div className="t-meta">
                  {h.role} · {h.success ? "success" : "failed"}
                </div>
              </li>
            ))}
          </ul>
        </details>
      )}
    </div>
  );
}

function AssignmentActions({
  item,
  user,
  act,
  offered,
  active,
  assignmentId,
  sampleId,
}: {
  item: any;
  user: UserInfo;
  act: ActFn;
  offered: boolean;
  active: boolean;
  assignmentId: string;
  sampleId?: string;
}) {
  const role = user.activeRole;
  const [declineReason, setDeclineReason] = useState("");
  const [containerType, setContainerType] = useState("");
  const [temp, setTemp] = useState("");
  const [progress, setProgress] = useState("in_transit");
  const [lat, setLat] = useState("");
  const [lon, setLon] = useState("");
  const [seq, setSeq] = useState("1");
  const [receiverId, setReceiverId] = useState("");
  const [toAssignmentId, setToAssignmentId] = useState("");
  const [handoffId, setHandoffId] = useState("");
  const [handoffSide, setHandoffSide] = useState("receiver");
  const [exceptionReason, setExceptionReason] = useState("");

  return (
    <div className="section-actions">
      {offered && (
        <>
          <button
            className="primary"
            onClick={() =>
              act(
                "/api/accept-assignment",
                { assignmentId, idempotencyKey: idemKey() },
                "Assignment accepted"
              )
            }
          >
            Accept
          </button>
          <input
            placeholder="Decline reason (optional)"
            value={declineReason}
            onChange={(e) => setDeclineReason(e.target.value)}
          />
          <button
            className="danger"
            onClick={() =>
              act(
                "/api/decline-assignment",
                {
                  assignmentId,
                  reason: declineReason || undefined,
                  declinedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Assignment declined"
              )
            }
          >
            Decline
          </button>
        </>
      )}

      {active && (
        <>
          <select value={progress} onChange={(e) => setProgress(e.target.value)}>
            {PROGRESS_STATUSES.map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </select>
          <button
            onClick={() =>
              act(
                "/api/update-assignment-progress",
                { assignmentId, status: progress, occurredAt: nowIso(), idempotencyKey: idemKey() },
                "Progress recorded"
              )
            }
          >
            Record progress
          </button>
        </>
      )}

      {active && role === "collection_professional" && item.kind === "collection" && sampleId && (
        <>
          <input
            placeholder="Container type"
            value={containerType}
            onChange={(e) => setContainerType(e.target.value)}
          />
          <input
            placeholder="Observed °C"
            value={temp}
            onChange={(e) => setTemp(e.target.value)}
            style={{ width: 110 }}
          />
          <button
            className="primary"
            onClick={() =>
              act(
                "/api/collect-and-seal-sample",
                {
                  sampleId,
                  assignmentId,
                  collectedAt: nowIso(),
                  containerType,
                  observedTemperatureC: Number(temp),
                  idempotencyKey: idemKey(),
                },
                "Sample collected and sealed"
              )
            }
          >
            Collect &amp; seal
          </button>
        </>
      )}

      {active && (role === "collection_professional" || role === "delivery_partner") && (
        <>
          <input
            placeholder="Lat"
            value={lat}
            onChange={(e) => setLat(e.target.value)}
            style={{ width: 90 }}
          />
          <input
            placeholder="Lon"
            value={lon}
            onChange={(e) => setLon(e.target.value)}
            style={{ width: 90 }}
          />
          <input
            placeholder="Seq"
            value={seq}
            onChange={(e) => setSeq(e.target.value)}
            style={{ width:  width60 }}
          />
          <button
            onClick={() =>
              act(
                "/api/record-worker-location",
                {
                  assignmentId,
                  coordinate: { latitude: Number(lat), longitude: Number(lon) },
                  sequence: Number(seq),
                  recordedAt: nowIso(),
                },
                "Location recorded"
              )
            }
          >
            Record location
          </button>
        </>
      )}

      {active && sampleId && (
        <>
          <input
            placeholder="Receiver user ID"
            value={receiverId}
            onChange={(e) => setReceiverId(e.target.value)}
          />
          <input
            placeholder="Next assignment ID"
            value={toAssignmentId}
            onChange={(e) => setToAssignmentId(e.target.value)}
          />
          <button
            onClick={() =>
              act(
                "/api/initiate-handoff",
                {
                  sampleId,
                  fromAssignmentId: assignmentId,
                  toAssignmentId: toAssignmentId.trim(),
                  receiverId: receiverId.trim(),
                  initiatedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Handoff initiated"
              )
            }
          >
            Initiate handoff
          </button>
          <input
            placeholder="Handoff ID"
            value={handoffId}
            onChange={(e) => setHandoffId(e.target.value)}
          />
          <select value={handoffSide} onChange={(e) => setHandoffSide(e.target.value)}>
            <option value="receiver">as receiver</option>
            <option value="sender">as sender</option>
          </select>
          <button
            onClick={() =>
              act(
                "/api/confirm-handoff",
                {
                  handoffId: handoffId.trim(),
                  confirmationSide: handoffSide,
                  confirmedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Handoff confirmed"
              )
            }
          >
            Confirm handoff
          </button>
        </>
      )}

      {active && sampleId && (
        <>
          <input
            placeholder="Checkpoint container"
            value={containerType}
            onChange={(e) => setContainerType(e.target.value)}
          />
          <input
            placeholder="Checkpoint °C"
            value={temp}
            onChange={(e) => setTemp(e.target.value)}
            style={{ width: 120 }}
          />
          <button
            onClick={() =>
              act(
                "/api/record-handling-checkpoint",
                {
                  sampleId,
                  assignmentId,
                  containerType,
                  observedTemperatureC: Number(temp),
                  recordedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Checkpoint recorded"
              )
            }
          >
            Record checkpoint
          </button>
        </>
      )}

      {active && role === "laboratory_team" && sampleId && item.laboratoryId && (
        <>
          <button
            className="primary"
            onClick={() =>
              act(
                "/api/confirm-laboratory-receipt",
                {
                  sampleId,
                  laboratoryId: item.laboratoryId,
                  receivedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Sample received at laboratory"
              )
            }
          >
            Confirm receipt
          </button>
          <input
            placeholder="Exception reason"
            value={exceptionReason}
            onChange={(e) => setExceptionReason(e.target.value)}
          />
          <button
            className="danger"
            onClick={() =>
              act(
                "/api/record-laboratory-exception",
                {
                  sampleId,
                  laboratoryId: item.laboratoryId,
                  reason: exceptionReason,
                  observedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Exception recorded"
              )
            }
          >
            Record exception
          </button>
        </>
      )}
    </div>
  );
}
"}

{"command":"create","path":"/workspace/web/src/views/SampleDetail.tsx","file_text":"import { useCallback, useEffect, useState } from "react";
import { get, post } from "../api";
import { errText, fmtTime, shortId } from "../util";

interface Props {
  sampleId: string;
  onBack: () => void;
}

export default function SampleDetail({ sampleId, onBack }: Props) {
  const [state, setState] = useState<any | null>(null);
  const [lifecycle, setLifecycle] = useState<any | null>(null);
  const [journey, setJourney] = useState<any | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    try {
      const [st, lc] = await Promise.all([
        get<any>(`/api/read-sample-state/${sampleId}`),
        post<any>("/api/read-sample-lifecycle", { sampleId }),
      ]);
      setState(st);
      setLifecycle(lc);
      if (lc.activeJourneyId) {
        try {
          const j = await post<any>("/api/read-journey-plan", { journeyId: lc.activeJourneyId });
          setJourney(j);
        } catch {
          setJourney(null);
        }
      } else {
        setJourney(null);
      }
    } catch (e) {
      setError(errText(e));
    }
  }, [sampleId]);

  useEffect(() => {
    load();
    const t = setInterval(load, 15000);
    return () => clearInterval(t);
  }, [load]);

  const exception = lifecycle?.exception || state?.exception;
  const timeline: any[] = lifecycle?.timeline || state?.timeline || [];
  const ordered = [...timeline].sort(
    (a, b) => new Date(a.occurredAt).getTime() - new Date(b.occurredAt).getTime()
  );
  const legs: any[] = journey?.legs || [];
  const completedLegs: string[] = lifecycle?.completedLegIds || state?.completedLegIds || [];

  return (
    <div>
      <button onClick={onBack}>← Back</button>
      <section className="panel" style={{ marginTop: 12 }} aria-label="Sample details">
        <h2>
          Sample <span className="mono">{shortId(sampleId)}</span>
        </h2>
        {error && (
          <div className="error-box" role="alert">
            {error}
          </div>
        )}
        {(state || lifecycle) && (
          <>
            <div className="row" style={{ marginBottom: 8 }}>
              <span className="badge info">Status: {lifecycle?.status || state?.status}</span>
              {(lifecycle?.sealed ?? state?.sealed) ? (
                <span className="badge ok">Sealed</span>
              ) : (
                <span className="badge warn">Not sealed</span>
              )}
              {exception ? (
                <span className="badge err" role="alert">
                  Exception: {exception.reason || exception.type || "flagged"}
                </span>
              ) : (
                <span className="badge ok">No exception</span>
              )}
              {(lifecycle?.locationStale ?? state?.locationStale) ? (
                <span className="badge warn">Location stale</span>
              ) : (
                <span className="badge ok">Location fresh</span>
              )}
            </div>
            <table className="data">
              <tbody>
                <tr>
                  <th>Current custodian</th>
                  <td className="mono">
                    {shortId(lifecycle?.currentHolderId || state?.currentHolderId)}
                  </td>
                </tr>
                <tr>
                  <th>Last known location</th>
                  <td>
                    {(() => {
                      const loc = lifecycle?.latestLocation || state?.latestLocation;
                      return loc
                        ? `${loc.latitude?.toFixed?.(5) ?? loc.latitude}, ${
                            loc.longitude?.toFixed?.(5) ?? loc.longitude
                          }`
                        : "—";
                    })()}
                  </td>
                </tr>
                <tr>
                  <th>Last update</th>
                  <td>
                    {fmtTime(
                      lifecycle?.locationRecordedAt ||
                        state?.locationRecordedAt ||
                        state?.lastUpdateAt
                    )}
                  </td>
                </tr>
                <tr>
                  <th>Route progress</th>
                  <td>
                    {legs.length > 0
                      ? `${completedLegs.length} of ${legs.length} legs completed`
                      : `${completedLegs.length} legs completed`}
                    {journey?.status && <> · journey {journey.status}</>}
                    {journey?.estimatedDeliveryAt && (
                      <> · ETA {fmtTime(journey.estimatedDeliveryAt)}</>
                    )}
                  </td>
                </tr>
                {lifecycle?.receivedLaboratoryId && (
                  <tr>
                    <th>Received at laboratory</th>
                    <td className="mono">{shortId(lifecycle.receivedLaboratoryId)}</td>
                  </tr>
                )}
              </tbody>
            </table>
          </>
        )}
      </section>

      {journey && (
        <section className="panel" aria-label="Journey">
          <h2>Journey</h2>
          <p className="muted">
            mode {journey.routeMode || "—"} · plan version {journey.planVersion ?? "—"} · status{" "}
            {journey.status || "—"}
          </p>
          {Array.isArray(journey.orderedStops) && journey.orderedStops.length > 0 && (
            <ol>
              {journey.orderedStops.map((s: any, i: number) => (
                <li key={i}>
                  {s.locationId ? shortId(s.locationId) : s.kind || "stop"}{" "}
                  <span className="muted">{s.plannedArrivalAt ? fmtTime(s.plannedArrivalAt) : ""}</span>
                </li>
              ))}
            </ol>
          )}
          {legs.length > 0 && (
            <table className="data">
              <thead>
                <tr>
                  <th>Leg</th>
                  <th>From</th>
                  <th>To</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {legs.map((l: any, i: number) => (
                  <tr key={l.assignmentId || l.legId || i}>
                    <td>{l.sequence ?? i + 1}</td>
                    <td className="mono">{shortId(l.fromLocationId)}</td>
                    <td className="mono">{shortId(l.toLocationId)}</td>
                    <td>{l.status || (completedLegs.includes(l.assignmentId) ? "completed" : "—")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>
      )}

      <section className="panel" aria-label="Status history">
        <h2>Status history</h2>
        {ordered.length === 0 && <p className="muted">No history yet.</p>}
        <ul className="timeline">
          {ordered.map((e, i) => (
            <li key={e.eventId ?? i}>
              <div className="t-time">{fmtTime(e.occurredAt)}</div>
              <div className="t-action">{e.action}</div>
              <div className="t-meta">
                {e.role ? `${e.role} · ` : ""}
                {e.success === false ? "failed" : "success"}
                {e.entityType ? ` · ${e.entityType}` : ""}
              </div>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}
"}

{"command":"create","path":"/workspace/web/src/views/MonitorView.tsx","file_text":"import { FormEvent, useCallback, useEffect, useState } from "react";
import { post } from "../api";
import { errText, fmtTime, idemKey, shortId } from "../util";

interface Props {
  onOpenSample: (sampleId: string) => void;
}

export default function MonitorView({ onOpenSample }: Props) {
  const [ops, setOps] = useState<any | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    try {
      const data = await post<any>("/api/read-operations-state", {});
      setOps(data);
      setError(null);
    } catch (e) {
      setError(errText(e));
    }
  }, []);

  useEffect(() => {
    refresh();
    const t = setInterval(refresh, 15000);
    return () => clearInterval(t);
  }, [refresh]);

  const act = async (path: string, body: Record<string, any>, ok: string) => {
    setError(null);
    setNotice(null);
    try {
      await post(path, body);
      setNotice(ok);
      await refresh();
    } catch (e) {
      setError(errText(e));
    }
  };

  if (error && !ops) {
    return (
      <div className="error-box" role="alert">
        {error}
      </div>
    );
  }
  if (!ops) return <p className="muted">Loading operations state…</p>;

  const samples: any[] = ops.samples || [];
  const workers: any[] = ops.workers || [];
  const locations: any[] = ops.locations || [];
  const connections: any[] = ops.connections || [];
  const routes: any[] = ops.routes || [];
  const handoffs: any[] = ops.handoffs || [];
  const delays: any[] = ops.delays || [];
  const exceptions: any[] = ops.exceptions || [];

  return (
    <div>
      {error && (
        <div className="error-box" role="alert">
          {error}
        </div>
      )}
      {notice && (
        <div className="info-box" aria-live="polite">
          {notice}
        </div>
      )}

      <section className="panel" aria-label="Samples">
        <h2>Samples ({samples.length})</h2>
        {samples.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Sample</th>
                <th>Status</th>
                <th>Holder</th>
                <th>Deadline</th>
                <th>Freshness</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {samples.map((s) => (
                <tr key={s.sampleId}>
                  <td className="mono">{shortId(s.sampleId)}</td>
                  <td>
                    <span className="badge info">{s.status}</span>
                    {s.exception && <span className="badge err">Exception</span>}
                  </td>
                  <td className="mono">{shortId(s.currentHolderId)}</td>
                  <td>{fmtTime(s.deliveryDeadline)}</td>
                  <td>
                    {s.locationStale ? (
                      <span className="badge warn">Stale</span>
                    ) : (
                      <span className="badge ok">Fresh</span>
                    )}
                  </td>
                  <td>
