{"command":"create","path":"/workspace/web/src/views/MapView.tsx","file_text":"import { useEffect, useRef, useState } from "react";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import { Protocol } from "pmtiles";
import { post } from "../api";
import type { UserInfo } from "../types";

let protocolRegistered = false;
function ensureProtocol() {
  if (!protocolRegistered) {
    const protocol = new Protocol();
    maplibregl.addProtocol("pmtiles", protocol.tile);
    protocolRegistered = true;
  }
}

interface Props {
  user: UserInfo;
}

export default function MapView({ user }: Props) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [overlayNote, setOverlayNote] = useState<string>("");

  useEffect(() => {
    ensureProtocol();
    if (!containerRef.current || mapRef.current) return;
    const map = new maplibregl.Map({
      container: containerRef.current,
      style: "/map-assets/style.json",
      center: [77.5946, 12.9716],
      zoom: 10,
      attributionControl: { compact: true },
    });
    map.addControl(new maplibregl.NavigationControl(), "top-right");
    map.on("error", (e) => {
      setError(e.error?.message || "Map error");
    });
    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    let cancelled = false;

    const clearMarkers = () => {
      markersRef.current.forEach((m) => m.remove());
      markersRef.current = [];
    };

    const addMarker = (
      lngLat: [number, number],
      color: string,
      label: string
    ) => {
      const map = mapRef.current;
      if (!map) return;
      const el = document.createElement("div");
      el.style.width = "14px";
      el.style.height = "14px";
      el.style.borderRadius = "50%";
      el.style.background = color;
      el.style.border = "2px solid #fff";
      el.style.boxShadow = "0 0 2px rgba(0,0,0,0.5)";
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat(lngLat)
        .setPopup(new maplibregl.Popup({ offset: 12 }).setText(label))
        .addTo(map);
      markersRef.current.push(marker);
    };

    const loadOverlay = async () => {
      const map = mapRef.current;
      if (!map) return;
      const canSeeOps = ["dispatcher", "administrator"].includes(user.activeRole);
      try {
        if (canSeeOps) {
          const ops = await post<any>("/api/read-operations-state", {});
          if (cancelled) return;
          clearMarkers();
          (ops.locations || []).forEach((l: any) => {
            if (l.coordinate)
              addMarker(
                [l.coordinate.longitude, l.coordinate.latitude],
                l.active ? "#1a5fb4" : "#9aa0a6",
                `Location: ${l.name} (${l.active ? "active" : "inactive"})`
              );
          });
          (ops.workers || []).forEach((w: any) => {
            if (w.lastLocation)
              addMarker(
                [w.lastLocation.longitude, w.lastLocation.latitude],
                "#26a269",
                `Worker: ${w.username || w.workerId}`
              );
          });
          (ops.samples || []).forEach((s: any) => {
            if (s.latestLocation)
              addMarker(
                [s.latestLocation.longitude, s.latestLocation.latitude],
                s.locationStale ? "#e5a50a" : "#c01c28",
                `Sample ${s.sampleId} — ${s.status}${s.locationStale ? " (stale)" : ""}`
              );
          });
          const lines = {
            type: "FeatureCollection",
            features: (ops.connections || [])
              .map((c: any) => {
                const from = (ops.locations || []).find(
                  (l: any) => l.locationId === c.fromLocationId
                );
                const to = (ops.locations || []).find(
                  (l: any) => l.locationId === c.toLocationId
                );
                if (!from?.coordinate || !to?.coordinate) return null;
                return {
                  type: "Feature",
                  properties: { active: c.active, cooled: c.cooled },
                  geometry: {
                    type: "LineString",
                    coordinates: [
                      [from.coordinate.longitude, from.coordinate.latitude],
                      [to.coordinate.longitude, to.coordinate.latitude],
                    ],
                  },
                };
              })
              .filter(Boolean),
          };
          const draw = () => {
            if (!mapRef.current) return;
            if (map.getSource("network-lines")) {
              (map.getSource("network-lines") as maplibregl.GeoJSONSource).setData(lines as any);
            } else {
              map.addSource("network-lines", { type: "geojson", data: lines as any });
              map.addLayer({
                id: "network-lines",
                type: "line",
                source: "network-lines",
                paint: {
                  "line-color": [
                    "case",
                    ["get", "active"],
                    ["case", ["get", "cooled"], "#3b82f6", "#7c3aed"],
                    "#c0c4c8",
                  ],
                  "line-width": 2,
                  "line-dasharray": [2, 1],
                },
              });
            }
          };
          if (map.isStyleLoaded()) draw();
          else map.once("load", draw);
          setOverlayNote(
            `${(ops.locations || []).length} locations · ${
              (ops.connections || []).length
            } connections · ${(ops.workers || []).length} workers · ${
              (ops.samples || []).length
            } samples`
          );
        } else {
          const snap = await post<any>("/api/read-serviceability-snapshot", {});
          if (cancelled) return;
          clearMarkers();
          (snap.regions || []).forEach((r: any) => {
            const c = r.centroid || r.center || r.coordinate;
            if (c)
              addMarker(
                [c.longitude, c.latitude],
                "#1a5fb4",
                `Collection point coverage ${r.coverageKm ?? ""} km`
              );
          });
          setOverlayNote(
            `Serviceability version ${snap.version} · ${snap.activeCollectionPointCount} active collection points`
          );
        }
        setError(null);
      } catch (e: any) {
        if (!cancelled) setError(e?.message || String(e));
      }
    };

    loadOverlay();
    const t = setInterval(loadOverlay, 20000);
    return () => {
      cancelled = true;
      clearInterval(t);
    };
  }, [user.activeRole]);

  return (
    <div>
      <section className="panel" aria-label="Live map">
        <h2>Live network map</h2>
        <p className="muted">
          Basemap tiles are served locally from bundled PMTiles assets (© OpenStreetMap
          contributors). {overlayNote}
        </p>
        {error && (
          <div className="error-box" role="alert">
            {error}
          </div>
        )}
        <div
          ref={containerRef}
          role="application"
          aria-label="Network map"
          style={{ width: "100%", height: 520, borderRadius: 8, overflow: "hidden" }}
        />
      </section>
    </div>
  );
}
"}

